function countArrangement(n) {
  const used = new Array(n + 1).fill(false);
  let count = 0;
  const place = (position) => {
    if (position === 0) {
      count++;
      return;
    }
    for (let value = 1; value <= n; value++) {
      if (used[value]) {
        continue;
      }
      if (value % position !== 0 && position % value !== 0) {
        continue;
      }
      used[value] = true;
      place(position - 1);
      used[value] = false;
    }
  };
  place(n);
  return count;
}

