function countArrangement(n) {
  // Bitmask DP: ways[mask] counts the valid ways to fill the first popcount(mask) positions with the numbers in mask.
  const full = (1 << n) - 1;
  const ways = new Array(full + 1).fill(0);
  ways[0] = 1;
  for (let mask = 0; mask < full; mask++) {
    if (!ways[mask]) continue;
    let pos = 1;
    for (let m = mask; m; m &= m - 1) pos++;
    for (let v = 1; v <= n; v++) {
      const bit = 1 << (v - 1);
      if (mask & bit) continue;
      if (v % pos === 0 || pos % v === 0) ways[mask | bit] += ways[mask];
    }
  }
  return ways[full];
}

